html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None) -%}
    {% if letter_head and not no_letterhead %}
        <div class="letter-head">{{ letter_head }}</div>
    {% endif %}
    <h2 class="text-center">{{ _(doc.doctype) }}</h2>
    {%- if doc.meta.is_submittable and doc.docstatus==2-%}
    <div class="text-center" document-status="cancelled">
        <h4 style="margin: 0px;">{{ _("CANCELLED") }}</h4>
    </div>
    {%- endif -%}
{%- endmacro -%}

{% for page in layout %}
    <div class="page-break">
        <div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
            {{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
        </div>

        {% if print_settings.repeat_header_footer %}
            <div id="footer-html" class="visible-pdf">
                {% if not no_letterhead and footer %}
                <div class="letter-head-footer">
                    {{ footer }}
                </div>
                {% endif %}
                <p class="text-center small page-number visible-pdf">
                    {{ _("Page {0} of {1}").format('<span class="page"></span>', '<span class="topage"></span>') }}
                </p>
            </div>
        {% endif %}

        <style>
            .qcs-table {
                width: 100%;
                border: 1px solid #d1d8dd;
                border-collapse: collapse;
                font-size: 12px;
            }
            .qcs-table th,
            .qcs-table td {
                border: 1px solid #d1d8dd;
                padding: 6px;
            }
            .qcs-table th {
                background-color: #f7fafc;
                text-transform: uppercase;
            }
            .text-right { text-align: right; }
            .text-center { text-align: center; }
            .mb-2 { margin-bottom: 12px; }
            .section-break { margin-top: 20px; }
        </style>

        <!-- Document Information -->
        <table class="qcs-table mb-2">
            <tr>
                <th style="width:25%">{{ _("Request For Quotation") }}</th>
                <td>{{ doc.request_for_quotation }}</td>
                <th style="width:25%">{{ _("Required Date") }}</th>
                <td>{{ frappe.utils.format_date(doc.required_date) }}</td>
            </tr>
            <tr>
                <th>{{ _("Prepared By") }}</th>
                <td>{{ doc.prepared_by }}</td>
                <th>{{ _("Compare By") }}</th>
                <td>{{ doc.compare_quotation_by }}</td>
            </tr>
        </table>

        <!-- Quotations Summary -->
        <h4 class="section-break">{{ _("Quotations") }}</h4>
        <table class="qcs-table mb-2">
            <thead>
                <tr>
                    <th class="text-center" style="width:5%">{{ _("Sr") }}</th>
                    <th style="width:20%">{{ _("Supplier") }}</th>
                    <th style="width:20%">{{ _("Quotation") }}</th>
                    <th style="width:15%">{{ _("Date") }}</th>
                    <th class="text-right" style="width:15%">{{ _("Grand Total") }}</th>
                </tr>
            </thead>
            {% for q in doc.quotations %}
            <tr>
                <td class="text-center">{{ loop.index }}</td>
                <td>{{ q.supplier }}</td>
                <td>{{ q.quotation }}</td>
                <td>{{ frappe.utils.format_date(q.date) }}</td>
                <td class="text-right">{{ q.get_formatted("grand_total", doc) }}</td>
            </tr>
            {% endfor %}
        </table>

        <!-- Supplier-wise Comparison (pivot) -->
        <h4 class="section-break">{{ _("Supplier-wise Comparison") }}</h4>
        {% set suppliers   = doc.quotations | map(attribute='supplier') | list %}
        {% set items_list  = [] %}
        {% for d in doc.quotation_items %}
            {% if d.item_code not in items_list %}{% set _ = items_list.append(d.item_code) %}{% endif %}
        {% endfor %}

        <table class="qcs-table pivot-table">
            <thead>
                <tr>
                    <th rowspan="2" class="text-center" style="width:3%">{{ _("Sr") }}</th>
                    <th rowspan="2" style="width:22%">{{ _("Item Name") }}</th>
                    <th rowspan="2" class="text-right" style="width:6%; border-right: 2px solid #000;">{{ _("Qty") }}</th>
                    {% for s in suppliers %}
                        <th colspan="4" class="text-center" style="border-right: 2px solid #000;">{{ s }}</th>
                    {% endfor %}
                </tr>
                <tr>
                    {% for s in suppliers %}
                        <th class="text-right" style="width:6%">{{ _("Price") }}</th>
                        <th class="text-right" style="width:6%">{{ _("Dis (₹)") }}</th>
                        <th class="text-right" style="width:6%">{{ _("Rate") }}</th>
                        <th class="text-right" style="width:7%; border-right: 2px solid #000;">{{ _("Amount") }}</th>
                    {% endfor %}
                </tr>
            </thead>
            <tbody>
                {% for code in items_list %}
                {% set base = (doc.quotation_items | selectattr('item_code','equalto',code) | list | first) %}
                <tr>
                    <td class="text-center">{{ loop.index }}</td>
                    <td>{{ base.item_name if base else "" }}</td>
                    <td class="text-right" style="border-right: 2px solid #000;">{{ base.get_formatted('qty',0) if base else "" }}</td>

                    {% for sup in suppliers %}
                        {% set row = (doc.quotation_items
                                       | selectattr('item_code','equalto',code)
                                       | selectattr('supplier','equalto',sup) | list | first) %}

                        {# compute tax amount #}
                        {% if row %}
                            {% set plr = row.price_list_rate %}
                            {% set dp = row.discount_percentage or 0 %}
                            {% set discount = plr * dp / 100 %}

                            <td class="text-right">{{ frappe.utils.fmt_money(plr or 0) }}</td>
                            <td class="text-right">{{ frappe.utils.fmt_money(discount or 0) }}</td>
                            <td class="text-right">{{ frappe.utils.fmt_money(row.rate) }}</td>
                            <td class="text-right" style="border-right: 2px solid #000;">{{ row.get_formatted('amount',doc) }}</td>
                        {% else %}
                            <td class="text-right">-</td>
                            <td class="text-right">-</td>
                            <td class="text-right">-</td>
                            <td class="text-right" style="border-right: 2px solid #000;">-</td>
                        {% endif %}
                    {% endfor %}
                </tr>
                {% endfor %}

                {# ---------- supplier subtotals ---------- #}
                <tr>
                    <td colspan="3" style="border-right: 2px solid #000;"><b>{{ _("Basic Price") }}</b></td>
                    {% for sup in suppliers %}
                        {% set sub = namespace(net=0) %}
                        {% for qi in doc.quotation_items if qi.supplier==sup %}
                            {% set tp = (qi.sgst_rate or 0)+(qi.cgst_rate or 0)+(qi.igst_rate or 0) %}
                            {% set sub.net = sub.net + (qi.amount / (1+tp/100) if tp else qi.amount) %}
                        {% endfor %}
                        <td></td>                       {# blank price cell #}
                        <td></td>                       {# blank discount cell  #}
                        <td></td>                       {# blank rate cell  #}
                        <td class="text-right" style="border-right: 2px solid #000;"><b>{{ frappe.utils.fmt_money(sub.net) }}</b></td>
                    {% endfor %}
                </tr>

                <tr>
                    <td colspan="3" style="border-right: 2px solid #000;"><b>{{ _("Amount (incl. taxes & charges)") }}</b></td>
                    {% for sup in suppliers %}
                        {% set q = (doc.quotations | selectattr('supplier','equalto',sup) | list | first) %}
                        <td></td><td></td><td></td>
                        <td class="text-right" style="border-right: 2px solid #000;"><b>{{ q.get_formatted('grand_total',doc) if q else '' }}</b></td>
                    {% endfor %}
                </tr>
                <tr>
                    <td colspan="3" style="border-right: 2px solid #000;"><b>{{ _("User Remarks") }}</b></td>
                    {% for q in doc.quotations %}
                        <td colspan="4" class="text-right" style="border-right: 2px solid #000;">{{ q.custom_remarks or "" }}</td>
                    {% endfor %}
                </tr>
            </tbody>
        </table>

        {% if doc.items and doc.items|length > 0 %}
        <!-- Analysis Items Table -->
            <h4 class="section-break">{{ _("Analysis Items") }}</h4>
            <table class="qcs-table">
                <thead>
                    <tr>
                        <th class="text-center" style="width:4%">{{ _("Sr") }}</th>
                        <th style="width:14%">{{ _("Item Code") }}</th>
                        <th style="width:24%">{{ _("Item Name") }}</th>
                        <th style="width:16%">{{ _("Recommended Supplier") }}</th>
                        <th class="text-right" style="width:8%">{{ _("Qty") }}</th>
                        <th class="text-right" style="width:10%">{{ _("Rate") }}</th>
                        <th class="text-right" style="width:12%">{{ _("Amount") }}</th>
                    </tr>
                </thead>
                <tbody>
                    {% for row in doc.items %}
                        <tr>
                            <td class="text-center">{{ loop.index }}</td>
                            <td>{{ row.item_code }}</td>
                            <td>{{ row.item_name }}</td>
                            <td>{{ row.supplier }}</td>
                            <td class="text-right">{{ row.get_formatted('qty', 0) }}</td>
                            <td class="text-right">{{ row.get_formatted('rate', doc) }}</td>
                            <td class="text-right">{{ row.get_formatted('final_amount', doc) if row.final_amount else row.get_formatted('amount', doc) }}</td>
                        </tr>
                    {% endfor %}
                </tbody>
            </table>
        {% endif %}

        {% if doc.additional_remarks %}
            <div class="section-break" style="margin-top: 20px;">
                <h4>{{ _("Additional Remarks") }}</h4>
                <p>{{ doc.additional_remarks }}</p>
            </div>
        {% endif %}

        {% if doc.quotations %}
            <div class="section-break" style="margin-top: 20px;">
                <h4>{{ _("Supplier Terms & Conditions") }}</h4>
                {% for q in doc.quotations %}
                    {% if q.terms %}
                        <div style="margin-bottom: 12px;">
                            <div><strong>{{ q.supplier }}:</strong></div>
                            <div style="margin-left: 10px; white-space: pre-wrap; font-size: 12px;">
                                {{ q.terms }}
                            </div>
                        </div>
                      {% endif %}
                {% endfor %}
            </div>
        {% endif %}
    </div>
{% endfor %}
